1) backend/tests/test_fix_r7_issued_table.py (run by hand against the patched scratch copy: it passes). Also update test_fix_r3_api.py:364 to SCHEMA_VERSION == 3, as in the diff.
```python
"""Round 7 (audit pages-B-02): at the advisory tier the table a person keys is issued once a day, after the 23:00 solve, and re-issued only when it
is worth the threshold, the brand's table writes allow and the last issue is an hour old (plan Part 7.1 step 7). GET /control serves the issued table
(not each quarter's draft), counts the issues against the writes, hides their rupees from a viewer, and asks for a new key after a re-issue."""
from __future__ import annotations

import json
from datetime import datetime, timedelta, timezone

from gridlytics import delivery, plans, sites, store, twin
from test_fix_api import world  # noqa: F401  (world is a fixture)

PKT = timezone(timedelta(hours=5))
FALLBACK = {"on_expiry": "inverter_native", "min_soc_floor_pct": 20.0}


def _plan(w, day, discharge_from: int, status="active") -> tuple[str, dict]:
    """A plan whose table for `day` holds until `discharge_from`, discharges to 22:00 and holds to midnight."""
    t0 = twin.day_start_utc(day)
    slots = []
    for a, b, mode, floor in ((0, discharge_from, "hold", 60.0), (discharge_from, 22, "discharge", 20.0), (22, 24, "hold", 20.0)):
        slots.append({"start": f"{a:02d}:00", "end": f"{b % 24:02d}:00", "start_ts": t0 + a * 3600, "end_ts": t0 + b * 3600, "mode": mode,
                      "soc_floor_pct": floor, "soc_target_pct": floor, "max_discharge_w": 50_000 if mode == "discharge" else None, "max_charge_w": None,
                      "grid_charge": False, "gen_charge": False, "grid_cap_w": None, "export_allowed": False, "genset": None, "intent": mode})
    compiled = {"brand": "deye", "grammar": delivery.BRANDS["deye"], "days": [{"date": day.isoformat(), "slots": slots}], "fallback": FALLBACK}
    pid = store.new_id()
    iso = datetime.now(timezone.utc).isoformat(timespec="seconds")
    with w.use(), store.connect() as con:
        con.execute("INSERT INTO plans (id, site_id, generated_at, belief_time, valid_from, valid_until, mode, status, summary, steps, slots) "
                    "VALUES (?,?,?,?,?,?,?,?,?,?,?)", (pid, w.site, iso, iso, iso, iso, "a", status, "{}", "[]", json.dumps(compiled)))
    return pid, compiled


def test_the_table_to_key_is_issued_once_a_day_and_reissued_only_when_worth_it(world, monkeypatch):
    sid = world.site
    day = datetime.now(PKT).date()
    t0 = twin.day_start_utc(day)
    at = lambda h, m=0: t0 + h * 3600 + m * 60  # noqa: E731
    with world.use():
        sites.set_tier_capable(sid, "advisory_writes")
        sites.set_tier_allowed(sid, "advisory_writes", "test")
        site = sites.full(sid)
        nightly, comp = _plan(world, day, 18, status="superseded")
        assert plans._issue_tables(site, None, nightly, comp, t0 - 3600 + 300) is None        # the 23:05 solve the night before
        assert plans.issued_for(sid, day.isoformat())["plan_id"] == nightly
        gains = iter([200.0, 900.0, 900.0, 900.0, 900.0])
        monkeypatch.setattr(plans, "_reissue_gain", lambda *a: next(gains))
        later = [_plan(world, day, 17 if k % 2 else 19, status="superseded") for k in range(5)]
        decide = [plans._issue_tables(site, None, pid, c, t) for (pid, c), t in zip(later, (at(10), at(10, 15), at(10, 30), at(11, 30), at(12, 45)))]
        # before: every quarter's plan replaced the table to key in, with nothing counted against the writes
        assert [d["blocked"] for d in decide] == ["below_threshold", None, "too_soon", None, "budget_used"]
        assert [i["reason"] for i in plans.issued_tables(sid, day.isoformat())] == ["nightly", "event", "event"]
        latest = plans.issued_for(sid, day.isoformat())["plan_id"]
        assert latest == later[3][0]
        current, _ = _plan(world, day, 16)                                                     # this quarter's draft differs again
        with store.connect() as con:
            con.execute("INSERT INTO applied (id, site_id, plan_id, day_local, by, method, created) VALUES (?,?,?,?,?,?,?)",
                        ("m1", sid, later[1][0], day.isoformat(), "Installer", "installer_keyed",
                         datetime.fromtimestamp(at(10, 20), timezone.utc).isoformat(timespec="seconds")))
    c = world.c["admin"].get(f"/api/sites/{sid}/control").json()
    assert c["plan_id"] == current
    assert c["issued"] == [{"day": day.isoformat(), "plan_id": latest, "issued_at": plans._iso(at(11, 30)), "reason": "event", "gain_rs": 900.0}]
    assert c["compiled"]["days"][0]["slots"][1]["start"] == later[3][1]["days"][0]["slots"][1]["start"]    # the issued table, not the draft
    assert c["budget"] == {"table_writes_per_day": 3, "used_today": 3}
    # the table was re-issued after the 10:20 mark: what the inverter runs is the earlier one
    assert c["control"] == {"key": "unconfirmed", "label": "New table issued: key it in and mark it"}
    v = world.c["viewer"].get(f"/api/sites/{sid}/control").json()
    assert v["issued"][0]["plan_id"] == latest and "gain_rs" not in json.dumps(v)
```

