Backend, new file backend/tests/test_fix_r7_delivery.py (pages-B-04 and pages-B-05 add their tests to the same file):
```python
"""Round 7, Mode A delivery (audit pages-B-03, -04, -05; plan Part 7.1 step 4, DLV-02): the MDI cap is replayed only where something on site holds it,
is translated into the slots a person keys where nothing does, and the demand the keyed table reaches is reported; and each brand's table is in the
vendor's own layout, its rows exactly the grammar's fields, with the settings keyed once and what the brand cannot hold said. Test data: a synthetic
day; nothing reads the network."""
from __future__ import annotations

import numpy as np

from gridlytics import delivery, plans, twin

T0 = 1794000000 // 86400 * 86400 - 5 * 3600       # a Karachi midnight
BAT = {"E_nom": 1000.0, "eta_d": 0.95, "soc_min": 0.1, "soc_max": 0.95}


def _peak_day(e_nom: float = 1000.0) -> list[dict]:
    """A 400 kW load whose high quantile is 500 kW in the 18:00-22:00 peak (420 kW elsewhere), no PV: hold at 90 % to 18:00, discharge at 150 kW to
    22:00, then hold; the outage reserve 20 %."""
    out, soc = [], 90.0
    for i in range(96):
        peak = 72 <= i < 88
        dis = 150.0 if peak else 0.0
        st = {"t": T0 + 900 * i, "charge_kw": 0.0, "discharge_kw": dis, "grid_import_kw": 400.0 - dis, "grid_export_kw": 0.0, "load_kw": 400.0,
              "load_hi_kw": 500.0 if peak else 420.0, "pv_kw": 0.0, "pv_lo_kw": 0.0, "soc_start_pct": soc, "reserve_pct": 20.0, "genset_on": False,
              "reason": "discharge_peak_window" if peak else "hold_for_outage", "grid_present": 1.0, "grid_charge_permitted": True}
        soc -= dis * 0.25 / 0.95 / e_nom * 100
        st["soc_pct"] = round(soc, 2)
        out.append(st)
    return out


def test_a_slot_only_brand_gets_the_mdi_cap_as_discharge_room_and_floor_and_says_nothing_holds_it():
    steps = _peak_day()
    deye = delivery.compile_mode_a(steps, "deye", BAT, 20.0, 10.0, 300.0)
    assert deye["mdi"] == {"cap_kw": 300.0, "enforced": False}
    dis = next(s for s in deye["days"][0]["slots"] if s["mode"] == "discharge")
    assert dis["max_discharge_w"] == 200_000 and dis["mdi_shave_kw"] == 200.0          # 500 - 300, above the plan's 150 kW (keyed as Deye's power)
    assert dis["soc_floor_pct"] == 20.0                                                 # 84 points needed from 90 %: the reserve wins, never below it
    hold = next(s for s in deye["days"][0]["slots"] if s["mode"] == "hold")
    assert "mdi_shave_kw" not in hold and hold["max_discharge_w"] is None              # a hold cannot discharge on a slot-only device
    for comp in (delivery.compile_mode_a(steps, "huawei", BAT, 20.0, 10.0, 300.0),               # capacity control holds the cap
                 delivery.compile_mode_a(steps, "deye", BAT, 20.0, 10.0, 300.0, cap_enforced=True)):  # an edge holds it (closed loop)
        assert comp["mdi"]["enforced"] is True and all("mdi_shave_kw" not in s for d in comp["days"] for s in d["slots"])
    assert delivery.cap_enforced(deye) is False
    assert delivery.cap_enforced({"brand": "huawei", "days": []}) is True and delivery.cap_enforced({"brand": "deye", "days": []}) is False


def test_a_replay_holds_the_slots_grid_cap_only_where_something_on_site_holds_it():
    steps = _peak_day()
    slots = [s for d in delivery.compile_mode_a(steps, "deye", BAT, 20.0, 10.0, 300.0)["days"] for s in d["slots"]]
    ts = np.arange(steps[0]["t"], steps[-1]["t"] + 900, 60)
    assert np.isinf(twin.slots_policy(slots, ts, honour_cap=False)["grid_cap"]).all()
    assert np.isfinite(twin.slots_policy(slots, ts)["grid_cap"]).all()                     # the default keeps every other caller as it was


def test_the_plan_reports_the_demand_a_keyed_table_reaches_above_a_cap_nothing_holds():
