"""Round 7 (audit pages-B-07, UI-09): the plan table's Flags column and its past rows. Every step names the overrides it lies inside (`flags`), and
GET /plan/past gives the last hours as the plan in force then planned them and as measured, with no rupees for a viewer."""
from __future__ import annotations

import time
from datetime import datetime, timezone

import pytest

from gridlytics import forecast, plans, routes_plans, sites, telemetry
from test_fix_api import world  # noqa: F401  (world is a fixture)


def _iso(ts: int) -> str:
    return datetime.fromtimestamp(ts, timezone.utc).isoformat()


def _ready(world) -> int:
    """The fixture's site with PV, and the current quarter."""
    with world.use():
        sites.put_asset(world.site, "pv", {"kwp_dc": 200, "kw_ac": 180}, "test")
    return forecast.align(time.time())


def test_every_step_inside_an_override_names_it_in_flags(world):
    a, sid = world.c["admin"], world.site
    q = _ready(world)
    until = q + 2 * 3600
    r = a.post(f"/api/sites/{sid}/overrides", json={"kind": "reserve", "value": 60, "until": _iso(until), "reason": "r7"})
    assert r.status_code == 200, r.text
    with world.use():
        assert plans.tick(sid)["status"] == "active"
    steps = a.get(f"/api/sites/{sid}/plan").json()["plan"]["steps"]
    inside, after = [s for s in steps if s["t"] < until], [s for s in steps if s["t"] >= until]
    assert inside and all(s["flags"] == ["reserve"] for s in inside)
    assert after and all(s["flags"] == [] for s in after)


def test_the_past_rows_carry_the_plan_in_force_then_and_the_measured_values(world, monkeypatch):
    a, sid = world.c["admin"], world.site
    q = _ready(world)
    monkeypatch.setattr(routes_plans, "now_ts", lambda: q + 30)  # no quarter boundary between the ticks and the read
    with world.use():
        early = plans.tick(sid, at=q - 3 * 3600)
        late = plans.tick(sid, at=q - 3600)
        assert early["status"] == late["status"] == "active"
        telemetry.ingest(sid, [{"ts": m, "grid_present": 1, "pv_power_w": 0, "load_power_w": 120_000, "grid_power_w": 100_000,
                                "battery_power_w": 20_000, "battery_soc_est_pct": 55} for m in range(q - 1800, q, 60)], "edge")
    r = a.get(f"/api/sites/{sid}/plan/past", params={"hours": 24})
    assert r.status_code == 200, r.text
    rows = r.json()["steps"]
    assert len(rows) == 96 and rows[0]["t"] == q - 86400 and rows[-1]["t"] == q - 900
    by = {x["t"]: x for x in rows}
    assert by[q - 4 * 3600]["planned"] is None and by[q - 4 * 3600]["plan_id"] is None   # before the first plan, none was in force
    assert by[q - 2 * 3600]["plan_id"] == early["plan_id"] and by[q - 2 * 3600]["planned"]["t"] == q - 2 * 3600
    assert by[q - 900]["plan_id"] == late["plan_id"]
    act = by[q - 900]["actual"]
    assert act["load_kw"] == pytest.approx(120.0) and act["grid_kw"] == pytest.approx(100.0) and act["battery_kw"] == pytest.approx(20.0)
    assert act["soc_pct"] == pytest.approx(55.0) and act["grid_present"] == 1
    assert by[q - 2 * 3600]["actual"] is None                                             # no reading: null, never zeros


def test_a_viewer_s_past_rows_carry_the_energy_and_no_rupees(world, monkeypatch):
    sid = world.site
