```python
"""Round 7 (audit pages-B-08): the "it took" or "it did not take" card 30 minutes after a keyed table's first discharge slot in the peak (plan Part
9.5 and 7.6), computed by the tick, never by the nightly job alone; the day's class and its claim stay the nightly check's."""
from __future__ import annotations

import json
from datetime import date, datetime, timezone

import numpy as np
from test_fix_savings import company, make_site  # noqa: F401 (company is a fixture)

from gridlytics import alerts, plans, store, telemetry, twin, verify

D = date(2026, 10, 14)
T0 = twin.day_start_utc(D)
PEAK = (T0 + 18 * 3600, T0 + 22 * 3600)
DUE = PEAK[0] + 1800


def _slot(a, b, mode, floor):
    return {"start": f"{a:02d}:00", "end": f"{b % 24:02d}:00", "start_ts": T0 + a * 3600, "end_ts": T0 + b * 3600, "mode": mode,
            "soc_floor_pct": floor, "soc_target_pct": floor, "grid_charge": False, "max_discharge_w": None, "max_charge_w": None, "genset": None}


TABLE = [_slot(0, 18, "hold", 90.0), _slot(18, 22, "discharge", 20.0), _slot(22, 24, "hold", 20.0)]


def _keyed(name):
    """An advisory site whose inverter, left to itself, holds the battery for outages (native backup at 90 %), a plan with today's table and a
    mark made at 10:00 that morning."""
    sid = make_site(name=name, tier="advisory_writes", genset=False, native={"source": "entered", "work_mode": "backup", "backup_soc_pct": 90})
    pid = store.new_id()
    iso = lambda t: datetime.fromtimestamp(t, timezone.utc).isoformat(timespec="seconds")  # noqa: E731
    with store.connect() as con:
        con.execute("INSERT INTO plans (id, site_id, generated_at, belief_time, valid_from, valid_until, mode, status, steps, slots) "
                    "VALUES (?,?,?,?,?,?,?,?,?,?)", (pid, sid, iso(T0 - 3600), iso(T0 - 3600), iso(T0 - 3600), iso(T0 + 86400), "a", "active", "[]",
                                                     json.dumps({"days": [{"date": D.isoformat(), "slots": TABLE}]})))
        con.execute("INSERT INTO applied (id, site_id, plan_id, day_local, by, method, created) VALUES (?,?,?,?,?,?,?)",
                    (store.new_id(), sid, pid, D.isoformat(), "Installer", "installer_keyed", iso(T0 + 10 * 3600)))
    return sid


def _readings(sid, bat_kw, battery=True):
    """Grid-up minutes from 17:00 to 19:30: 150 kW of load, no PV, the battery's power by minute (kW, discharge positive) and its state of charge."""
    rows, soc = [], 90.0
    for t in range(T0 + 17 * 3600, T0 + 19 * 3600 + 1800, 60):
        b = bat_kw(t)
        soc -= b / 60 / 215 * 100
        rows.append((sid, t, "edge", 1.0, 0.0, 150_000.0, b * 1000 if battery else None, soc))
    telemetry.write_rows(rows, ("site_id", "ts", "source_id", "grid_present", "pv_power_w", "load_power_w", "battery_power_w", "battery_soc_bms_pct"))


def _peak(monkeypatch):
    monkeypatch.setattr(plans, "peak_mask", lambda conn, ts: (np.asarray(ts) >= PEAK[0]) & (np.asarray(ts) < PEAK[1]))


def test_a_keyed_table_gets_its_took_card_30_minutes_after_its_first_peak_slot(company, monkeypatch):
    _peak(monkeypatch)
    followed = _keyed("Took")
    _readings(followed, lambda t: 100.0 if t >= PEAK[0] else 0.0)
    early = verify.first_peak_check(followed, PEAK[0] + 20 * 60)
    assert early["verdict"] == "waiting" and early["due_ts"] == DUE and early["slot_start"] == "18:00"
    # before: nothing until the nightly job at 00:40 (verify.compute_day was the only caller of confirm_applied)
    early = verify.first_peak_check(followed, DUE + 60)
    assert early["verdict"] == "took" and early["max_discharge_kw"] == 100.0
    row = plans.applied_rows(followed)[0]
    assert row["early_check"]["verdict"] == "took"
    assert row["confirmation"] == "pending"      # the day's class and the claim stay the nightly check's
    # the inverter kept its native backup setting: the battery never discharged at 18:00
    ignored = _keyed("Did not take")
    _readings(ignored, lambda t: 0.0)
    assert verify.first_peak_check(ignored, DUE + 60)["verdict"] == "did_not_take"


def test_no_battery_reading_waits_and_a_did_not_take_raises_the_control_alert(company, monkeypatch):
    _peak(monkeypatch)
    blind = _keyed("Blind")
    _readings(blind, lambda t: 100.0, battery=False)
    assert verify.first_peak_check(blind, DUE + 60) == {**verify.first_peak_check(blind, DUE + 60), "verdict": "waiting", "reason": "no_battery_power"}
    ignored = _keyed("Ignored")
    _readings(ignored, lambda t: 0.0)
    monkeypatch.setattr(alerts, "settled", lambda site_id, plan, now: True)
    monkeypatch.setattr(plans, "current", lambda site_id: {"id": "p", "steps": []})
    alerts.evaluate(ignored, DUE + 60)
    assert "apply_did_not_take" in [a["rule"] for a in alerts.listing("active", ignored)]
```

