"""Round 7 (audit pages-B-14): the compare drawer compares against the captured native settings only (R8 2.9: "Needs the native-settings capture
and 1 day of data"); without a capture it answers why, never figures against an assumed self-use table labelled as captured."""
from __future__ import annotations

import json
from datetime import datetime, timezone

from gridlytics import sites, store, telemetry
from test_fix_api import _now, world  # noqa: F401  (world is a fixture)


def _plan_with_steps(w) -> str:
    """An active plan of two hours: 80 kW of load, no PV, the grid up, a peak-priced second hour and one self-use slot."""
    t0 = _now() // 900 * 900
    steps = [{"t": t0 + 900 * i, "local": "", "reason": "idle", "detail": "", "pv_forecast_kw": 0.0, "load_kw": 80.0, "critical_kw": 20.0,
              "grid_present": 1.0, "soc_start_pct": 60.0, "c_imp": 60.0 if i >= 4 else 30.0, "c_exp": 0.0, "peak": i >= 4, "genset_on": False}
             for i in range(8)]
    slots = {"days": [{"date": "x", "slots": [{"start_ts": t0, "end_ts": t0 + 7200, "mode": "self_use", "soc_floor_pct": 20.0, "soc_target_pct": 100.0,
                                                "grid_charge": False}]}], "fallback": None}
    iso = datetime.fromtimestamp(t0, timezone.utc).isoformat(timespec="seconds")
    with w.use(), store.connect() as con:
        con.execute("INSERT INTO plans (id, site_id, generated_at, belief_time, valid_from, valid_until, mode, status, summary, steps, slots) "
                    "VALUES (?,?,?,?,?,?,?,?,?,?,?)", ("pc1", w.site, iso, iso, iso, iso, "a", "active", "{}", json.dumps(steps), json.dumps(slots)))
    return "pc1"


def test_the_compare_drawer_needs_the_native_capture_and_a_day_of_data(world):
    sid, a = world.site, world.c["admin"]
    _plan_with_steps(world)
    # a monitor site with a battery, a plan and no capture: before, the native arm was self-use at 20 % and the page called it the captured settings
    assert a.get(f"/api/sites/{sid}/plan/compare").json() == {"compare": None, "reason": "no_capture"}
    with world.use():
        sites.capture_native(sid, {"source": "entered", "work_mode": "backup", "backup_soc_pct": 90}, "test")
    assert a.get(f"/api/sites/{sid}/plan/compare").json() == {"compare": None, "reason": "too_little_data"}
    with world.use():
        telemetry.ingest(sid, [{"ts": _now() // 60 * 60 - 2 * 86400, "grid_present": 1}], "edge")
    r = a.get(f"/api/sites/{sid}/plan/compare").json()
    assert r["compare"]["native"]["import_kwh"] > 0 and r["native"]["version"] == 1
    assert "energy_rs" not in json.dumps(world.c["viewer"].get(f"/api/sites/{sid}/plan/compare").json())
